    const cord=Math.max(2,Math.round(fh*.1));rect(g,m,yy,1,cord,INK);rect(g,m-2,yy+cord,5,1,INK);rect(g,m-3,yy+cord+1,7,2,INK);rect(g,m-2,yy+cord+3,5,1,lit?PAPER:DUSK);
