    if(a&&moving&&!still&&s.y%2&&a.from.y===s.y){const t=(time-a.start)/(a.end-a.start),dx=s.x>a.from.x?-1:1;for(let i=0;i<3;i++){const q=Math.min(1,t*1.2);rect(g,fx+dx*(5*k+i*2+q*4),fy-1-i-Math.round(q*2),1,1,lit?HAZE:MIST);}}
