 function errorMessage(code){return {blocked:'A wall, locked door or fixed device blocks that step. Use a ladder to change floors.',crate:'No room to push the crate. Crates cannot be pulled.',vent:'Stand on a vent before pressing E.',heavy:'The trophy is too heavy for this vent. Use the stairs.',light:'Move next to the wall switch marked L.',empty:'No EMP remaining.',finished:'This attempt has ended.'}[code]||'That action is not available.';}
 // CLICK-TO-TRAVEL: walk to a clicked cell one real turn at a time. Before every step the
 // move is simulated with the unchanged engine; the walk stops before any step that would
