 let travel=null,travelPreview=null,previewAt=0,resultTimer=0; // resultTimer: the result sheet waits ~800 ms so the caught/escape animation can play (none with MOTION OFF).
 function routeTo(t){if(!game||!t||t.x==null||t.y<0)return null;const l=game.level,s0=game.state;if(E.tile(l,t.x,t.y)==='#')return null;const key=p=>p.x+','+p.y,prev=new Map([[key(s0),null]]),q=[{x:s0.x,y:s0.y}];
  while(q.length){const c=q.shift();if(c.x===t.x&&c.y===t.y){const acts=[];let k=key(c);while(prev.get(k)){const [pk,a]=prev.get(k);acts.unshift(a);k=pk;}return acts;}
   for(const [a,[dx,dy]] of Object.entries(E.DIRS)){const n={x:c.x+dx,y:c.y+dy};if(prev.has(key(n))||E.solid(l,s0,n.x,n.y))continue;prev.set(key(n),[key(c),a]);q.push(n);}}return null;}
 function positions(acts){const out=[{x:game.state.x,y:game.state.y}];let x=game.state.x,y=game.state.y;for(const a of acts){x+=E.DIRS[a][0];y+=E.DIRS[a][1];out.push({x,y});}return out;}
 function stopTravel(msg){if(!travel)return;clearTimeout(travel.timer);travel=null;if(msg)toast(msg);}
 function startTravel(t){const acts=routeTo(t);if(!acts){toast('No open path to that cell right now.');return;}if(!acts.length)return;travel={target:{x:t.x,y:t.y},timer:0};travelPreview=null;travelStep();}
 function travelStep(){if(!travel)return;if(!game||game.state.status!=='playing'||paused||SDK?.paused()||$('modal').open||inspectMode||replay||editor?.active){stopTravel();return;}
  const s=game.state;if(s.x===travel.target.x&&s.y===travel.target.y){stopTravel();return;}
  const acts=routeTo(travel.target);if(!acts||!acts.length){stopTravel('The way ahead just closed. Plan your next move.');return;}
  const r=E.step(game.level,s,acts[0]);if(!r.changed){stopTravel();return;}
  if(r.state.status==='lost'||r.state.alarms>s.alarms){stopTravel('Stopped: the next step would be seen. Wait, or pick another route.');renderer.pulse?.(['switch'],performance.now());return;}
  act(acts[0]);const got=game.state.events.some(e=>['key','relic','intel','switch'].includes(e));if(got||game.state.status!=='playing'){stopTravel();return;}
  travel.timer=setTimeout(travelStep,save.reduced?60:125);}
 function act(a){if(inspectMode){scanAction(a);return;}if(!readyGame()||paused||SDK?.paused()||$('modal').open||game.state.status!=='playing')return;if(owned&&Date.now()-owned.checkedAt>300000)recheckOwned();const now=performance.now();if(now-lastInput<95)return;const q=E.step(game.level,game.state,a);if(!q.changed){toast(errorMessage(q.error));return;}lastInput=now;anim={from:{x:game.state.x,y:game.state.y},start:now,end:now+(save.reduced?0:140)};game.trail=[...(game.trail||[]),{x:game.state.x,y:game.state.y}].slice(-10);game.state=q.state;game.actions.push(a);renderer.pulse?.(q.state.events,now);beep(q.state.events.includes('alarm')?'alarm':q.state.events.includes('key')?'key':'step');hud();checkpoint();if(q.state.status!=='playing'){record();const g=game;clearTimeout(resultTimer);if(save.reduced)result();else resultTimer=setTimeout(()=>{if(game===g&&screen==='play'&&!replay&&!editor?.active)result();},800);}}
 function record(){if(game.recorded||game.shared||game.type==='test'||game.type==='fortify')return;game.recorded=true;const s=game.state,r={v:1,at:new Date().toISOString(),level:game.level,actions:[...game.actions],mode:s.mode,practice:game.practice,heroId:hero.tokenId,status:s.status};save.records.unshift(r);save.records=save.records.slice(0,30);if(s.status==='won'){const official=byId(game.level.id);if(official&&!game.practice&&F.planKey(official)===F.planKey(game.level))save.mastery[official.id]=F.mergeTarget(save.mastery[official.id],official,s,false);if(!save.done.includes(game.level.id))save.done.push(game.level.id);if(!game.practice&&(!official||F.planKey(official)===F.planKey(game.level))){const k=game.level.id+':'+s.mode;save.best[k]=Math.max(save.best[k]||0,E.score(game.level,s));}}persist();}
 // Result sheet: one verdict, one main action, the rest as quiet links. No alarm counter.
