 function exportCard(){if(!game)return;const c=document.createElement('canvas');c.width=960;c.height=720;const g=c.getContext('2d');P.rect(g,0,0,960,720,P.PAPER);P.rect(g,0,0,960,75);P.text(g,'RARE HEIST / CUTAWAY',24,18,3,P.PAPER);P.text(g,game.level.name,24,52,2,P.SIG);const v=document.createElement('canvas');HeistCutawayRenderer.create(v).render(game.level,game.state,{sample:hero,width:960,height:510,reduced:true,time:0});g.drawImage(v,0,76);P.rect(g,0,594,960,126);P.text(g,(game.state.status==='won'?({practice:'PRACTICE',ghost:'GHOST',clean:'CLEAN'}[medalOf(game.level,game.state)]||'CLEAN'):'SPOTTED')+' / '+game.state.turn+' TURNS / '+E.countIntel(game.state)+' INTEL',24,617,3,P.SIG);P.text(g,'ORIGINAL FRIEND #'+hero.tokenId+' / NO REAL FUNDS',24,670,2,P.PAPER);c.toBlob(blob=>{if(!blob)return toast('Export unavailable in this browser.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rare-heist-extraction.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');}
