 function drawPortrait(){const c=$('streetPage').querySelector('.hero-portrait');if(!c)return;const g=c.getContext('2d'),w=c.width,NIGHT='#151233',DUSK='#2c2766',HAZE='#5e56a8';g.imageSmoothingEnabled=false;P.rect(g,0,0,w,w,NIGHT);P.stipple(g,0,0,w,w,6,HAZE);const floor=126;for(let y=0;y<floor;y+=2){const half=14+Math.round(y*.36);P.rect(g,w/2-half,y,half*2,2,DUSK);if(!(y%4))for(let x=w/2-half+((y/2)%4?2:0);x<w/2+half;x+=4)P.rect(g,x,y,2,2,P.SIG);}P.rect(g,0,floor,w,w-floor,'#000');P.stipple(g,0,floor+4,w,w-floor-4,4,HAZE);for(let i=0;i<3;i++)P.rect(g,w/2-40+i*6,floor-2-i*2,80-i*12,2,P.SIG);P.sprite(g,hero,w/2,floor,6,'down',false,save.reduced?0:portraitFrame,true);}
